import { useState, useEffect, useCallback, useRef } from 'preact/hooks';
import { useDispatch, useSelector } from 'react-redux';
import SearchIcon from '@material-ui/icons/Search';
import CircularProgress from '@material-ui/core/CircularProgress';
import ArrowBackIcon from '@material-ui/icons/ArrowBack';
import CloseIcon from '@material-ui/icons/Close';
import CheckCircleOutlineIcon from '@material-ui/icons/CheckCircleOutline';
import cn from 'classnames';

import { sendMessage } from '../../../slice/thunks';
import { selectSendingState } from '../../../slice/selectors';

import Popover from '../../../../../shared/Popover';

import Preview from './Preview';
import fetchTenor from './fetchTenor';
import styles from './styles.module.scss';
import { UserDb } from '../../../../user/slice/types';
import { FunctionalComponent } from 'preact';
import useInfinityScroll from './useInfinityScroll';

const CATEGORIES = ['trending'];

interface Props {
  onClose: () => unknown,
  friend: UserDb,
  selectedRef?: any,
}

const SendGif: FunctionalComponent<Props> = ({ onClose, friend, selectedRef }: Props) => {
  const $scrollable = useRef<HTMLDivElement>();
  const dispatch = useDispatch();
  const sendingState = useSelector(selectSendingState);
  const paginationRef = useRef<Record<string, string>>({});

  const [state, setState] = useState({
    categories: CATEGORIES,
    resultsByCategory: {},

    category: CATEGORIES[0],
    isLoading: true,
    preview: null,
  });

  const searchForGifs = useCallback(async (category: string, q?: string, pos?: string) => {
    try {
      setState((prev) => {
        const isCached = prev.resultsByCategory[category];

        if (prev.category !== category) {
          $scrollable.current.scrollTop = 0;
        }

        return { ...prev, category, isLoading: !isCached };
      });

      const args: [string, Record<string, unknown>, boolean] =
        category === 'trending'
          ? ['/trending', {}, false]
          : ['/search', q ? { q } : { tag: category }, !!q];

      if (pos) {
        args[1].pos = pos;
      }

      const json = await fetchTenor<any>(...args);
      paginationRef.current[category] = json.next;
      setState((prev) => ({
        ...prev,
        isLoading: false,
        resultsByCategory: {
          ...prev.resultsByCategory,
          [category]: [
            ...(prev.resultsByCategory[category] || []),
            json.results,
          ],
        },
      }));
    } catch (e) {
      console.error('searchForGifs', e);
    }
  }, []);

  const [search, setSearch] = useState('');

  const loadMore = useCallback(() => {
    const { category } = state;
    const nextPage = paginationRef.current[category];

    if (nextPage) {
      searchForGifs(
        category,
        (search && state.categories.includes(search) ? search : null),
        nextPage
      );
    }
  }, [state, search]);

  useEffect(() => {
    if (!search) return;
    // eslint-disable-next-line @typescript-eslint/no-misused-promises
    const timeout = setTimeout(() => searchForGifs(search, search), 500);

    return () => {
      window.clearTimeout(timeout);
    };
  }, [search]);

  const handleType = (evt) => {
    // https://api.tenor.com/v1/search_suggestions?q=smile&key=LIVDSRZULELA&limit=5
    setSearch(evt.target.value);
    // https://api.tenor.com/v1/search?q=excited&key=LIVDSRZULELA&limit=8
    // https://api.tenor.com/v1/search?tag=dance&key=LIVDSRZULELA
  };

  useEffect(() => {
    const run = async () => {
      searchForGifs(CATEGORIES[0]);

      const json = await fetchTenor<any>('/categories');
      if (json && json.tags) {
        const list = json.tags.map((tag) => tag.searchterm);
        setState((prev) => ({ ...prev, categories: [...CATEGORIES, ...list] }));
      }
    };

    run();
  }, []);

  const onScroll = useInfinityScroll({ space: 100, loadMore });

  const previewGif = (item) => {
    setState({ ...state, preview: item });
  };

  const cancelPreview = () => {
    setState({ ...state, preview: null });
  };

  const handleSend = ({ message }) => {
    dispatch(
      sendMessage({
        message,
        thumbnailSrc: state.preview.media[0].tinymp4.preview,
        imgSrc: state.preview.media[0].mp4.url,
        type: 'TENOR',
        friendTo: friend.id,
      })
    );

    // setTimeout(onClose, 1000);

    // fetch(
    //   `https://api.tenor.com/v1/registershare?${new URLSearchParams({
    //     id: item.id,
    //     key: TENOR_API_KEY,
    //     q: search
    //   })}`
    // );
  };

  useEffect(() => {
    let timeout;
    if (sendingState.type === 'fulfilled') {
      timeout = setTimeout(onClose, 2000);
    }
    return () => {
      window.clearTimeout(timeout);
    };
  }, [sendingState.type]);

  const selectErrorMessage = () => {
    const defaultMsg = 'There was an error. Please try again.';
    try {
      const { error } = sendingState.error.content;
      return error === 'muted'
        ? `${friend.name} has disabled GIF messages.`
        : defaultMsg;
    } catch (e) {
      return defaultMsg;
    }
  };

  return (
    <div className={styles.sendGifContainer}>
      <Popover
        onClose={onClose}
        anchorEl={selectedRef}
        className={styles.sendGifPopover}
      >
        {sendingState.type === 'muted' && (
          <div className={styles.sentGif}>
            <div className={styles.text}>
              <div>To send GIFs you need to enable them again in settings.</div>
            </div>
          </div>
        )}

        {sendingState.type === 'pending' && <CircularProgress />}

        {sendingState.type === 'rejected' && (
          <div className={styles.sentGif}>
            <div className={styles.text}>
              <div>{selectErrorMessage()}</div>
            </div>
          </div>
        )}

        {sendingState.type === 'fulfilled' && (
          <div className={styles.sentGif}>
            <CheckCircleOutlineIcon />

            <div className={styles.text}>
              <div>GIF sent to</div>
              <div>{friend.name}</div>
            </div>
          </div>
        )}

        {!sendingState.type && state.preview && (
          <div className={styles.preview}>
            <header>
              <div className={styles.nav}>
                <button className={styles.navButton} onClick={cancelPreview}>
                  <ArrowBackIcon />
                </button>

                <button className={styles.navButton} onClick={onClose}>
                  <CloseIcon />
                </button>
              </div>
            </header>

            <Preview data={state.preview} onSubmit={handleSend} />
          </div>
        )}

        {!sendingState.type && !state.preview && (
          <>
            <header>
              <div className={styles.nav}>
                <h2>Send a GIF</h2>

                <button
                  className={cn(styles.closeButton, styles.navButton)}
                  onClick={onClose}
                >
                  <CloseIcon />
                </button>
              </div>

              <div className={styles.inputContainer}>
                <SearchIcon />
                <input
                  value={search}
                  type="text"
                  placeholder="Search for a GIF in Tenor"
                  onChange={handleType}
                />
              </div>
            </header>

            <ul className={styles.categoriesList}>
              {state.categories.slice(0, 12).map((category) => (
                <li
                  key={category}
                  className={state.category === category ? styles.active : ''}
                >
                  <a onClick={() => searchForGifs(category)}>{category}</a>
                </li>
              ))}
            </ul>

            <div>
              <div
                className={styles.gifsListContainer}
                onScroll={onScroll}
                ref={$scrollable}
              >
                {!state.isLoading && state.resultsByCategory[state.category] && (
                  <div>
                    {state.resultsByCategory[state.category].map((page, i) => (
                      <div key={i} className={styles.gifsList}>
                        {page
                          .filter(({ media }) => media.length && media[0].tinymp4)
                          .map((item) => (
                            <video
                              key={item.id}
                              loop
                              muted
                              autoPlay
                              onClick={() => previewGif(item)}
                              width={item.media[0].tinymp4.dims[0]}
                              height={item.media[0].tinymp4.dims[1]}
                            >
                              <source
                                src={item.media[0].tinymp4.url}
                                type="video/mp4"
                              />
                            </video>
                          ))}
                      </div>
                    ))}
                  </div>
                )}
              </div>

              {state.isLoading && <CircularProgress />}
            </div>
          </>
        )}
      </Popover>
    </div>
  );
};

export default SendGif;
